<?php declare(strict_types=1);$a=$data['asset'];$permissions=$data['user']['permissions']??[];$money=static fn($v)=>$a['currency'].' '.number_format((float)$v,2);$terminal=in_array($a['status'],['disposed','sold','scrapped','cancelled'],true);?>
<div class="module-stack asset-workspace"><nav class="workspace-breadcrumb"><a href="/office_app/public/assets">Fixed Assets</a><span>›</span><strong><?=e($a['asset_number'])?></strong></nav>
<header class="page-header"><div><p class="eyebrow"><?=e($a['category_name'])?></p><h1><?=e($a['asset_number'].' · '.$a['asset_name'])?></h1><p><?=e($a['location_name']??'No location')?> · <?=e($a['serial_number']??'No serial')?></p></div><span class="badge badge-muted"><?=e(strtoupper(str_replace('_',' ',$a['status'])))?></span></header>
<?php if(is_array($data['notice']??null)):?><div class="alert alert-success"><?=e($data['notice']['message']??'')?></div><?php endif;?><?php if(!empty($data['errors'])):?><div class="alert alert-danger"><?php foreach($data['errors'] as $error):?><div><?=e($error)?></div><?php endforeach;?></div><?php endif;?>
<section class="finance-summary-grid"><a class="card" href="#depreciation"><span>Depreciation</span><strong><?=e(count($a['schedule']))?></strong></a><a class="card" href="#history"><span>Journals / history</span><strong><?=e(count($a['history']))?></strong></a><a class="card" href="#transfers"><span>Transfers</span><strong><?=e(count($a['transfers']))?></strong></a><a class="card" href="#maintenance"><span>Maintenance</span><strong><?=e(count($a['maintenance']))?></strong></a></section>
<section class="card"><div class="finance-summary-grid"><div><span>Capitalized cost</span><strong><?=e($money((float)$a['acquisition_cost']+(float)$a['additional_capitalized_cost']))?></strong></div><div><span>Salvage</span><strong><?=e($money($a['salvage_value']))?></strong></div><div><span>Accumulated</span><strong><?=e($money($a['accumulated_depreciation']))?></strong></div><div><span>Net book value</span><strong><?=e($money($a['book_value']))?></strong></div></div></section>
<?php if($a['status']==='draft'&&in_array('assets.activate',$permissions,true)):?><section class="card"><h2>Activate</h2><form method="post" action="/office_app/public/assets/<?=e($a['asset_id'])?>/activate"><?=csrfField()?><label>In-service date <input type="date" name="in_service_date" min="<?=e($a['acquisition_date'])?>" value="<?=e($a['acquisition_date'])?>" required></label><button class="btn btn-primary">Activate and generate schedule</button></form></section><?php endif;?>
<section id="depreciation" class="card table-card"><div class="table-summary"><strong>Depreciation schedule</strong><span><?=e(count($a['schedule']))?> periods</span></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Period</th><th>Date</th><th>Amount</th><th>Accumulated</th><th>NBV after</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($a['schedule'] as $line):?><tr><td><?=e($line['period_number'])?></td><td><?=e($line['depreciation_date'])?></td><td><?=e($money($line['depreciation_amount']))?></td><td><?=e($money($line['accumulated_amount']))?></td><td><?=e($money($line['book_value_after']))?></td><td><?=e(strtoupper($line['status']))?></td><td><?php if($line['status']==='scheduled'&&!$terminal&&in_array('assets.depreciation.post',$permissions,true)):?><form method="post" action="/office_app/public/assets/<?=e($a['asset_id'])?>/depreciation/<?=e($line['depreciation_line_id'])?>/post"><?=csrfField()?><button class="btn btn-primary btn-compact">Post</button></form><?php elseif(!empty($line['journal_batch_id'])):?>Journal #<?=e($line['journal_batch_id'])?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if(!$terminal&&in_array('assets.manage',$permissions,true)):?><section class="finance-summary-grid"><article id="transfers" class="card"><h2>Transfer assignment</h2><form method="post" action="/office_app/public/assets/<?=e($a['asset_id'])?>/transfer"><?=csrfField()?><div class="form-field"><label>Department</label><select name="department_id"><option value="">Unassigned</option><?php foreach($data['departments'] as $d):?><option value="<?=e($d['department_id'])?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Custodian</label><select name="custodian_employee_id"><option value="">Unassigned</option><?php foreach($data['employees'] as $e):?><option value="<?=e($e['employee_id'])?>"><?=e($e['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Location</label><input name="location_name"></div><div class="form-field"><label>Reason</label><input name="reason" required></div><button class="btn btn-primary">Transfer</button></form></article><article id="maintenance" class="card"><h2>Record routine maintenance</h2><form method="post" action="/office_app/public/assets/<?=e($a['asset_id'])?>/maintenance"><?=csrfField()?><div class="form-field"><label>Type</label><select name="maintenance_type"><option value="repair">Repair</option><option value="preventive">Preventive</option><option value="corrective">Corrective</option><option value="inspection">Inspection</option></select></div><div class="form-field"><label>Description</label><input name="description" required></div><div class="form-field"><label>Vendor</label><input name="vendor_name"></div><div class="form-field"><label>Cost</label><input name="cost" type="number" min="0" step="0.01" value="0"></div><div class="form-field"><label>Date</label><input name="maintenance_date" type="date" value="<?=e(date('Y-m-d'))?>" required></div><button class="btn btn-primary">Record maintenance</button></form></article></section><?php endif;?>
<?php if(!$terminal&&in_array($a['status'],['active','fully_depreciated'],true)&&in_array('assets.dispose',$permissions,true)):?><section class="card"><h2>Dispose asset</h2><form method="post" action="/office_app/public/assets/<?=e($a['asset_id'])?>/dispose" class="finance-filter-form"><?=csrfField()?><div class="form-field"><label>Type</label><select name="disposal_type"><option value="sale">Sale</option><option value="scrap">Scrap</option><option value="write_off">Write-off</option></select></div><div class="form-field"><label>Date</label><input type="date" name="disposal_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="form-field"><label>Proceeds</label><input type="number" name="proceeds_amount" min="0" step="0.01" value="0"></div><div class="form-field"><label>Reason</label><input name="reason" required></div><button class="btn btn-danger">Post disposal</button></form></section><?php endif;?>
<section id="transfers" class="card table-card"><h2>Transfer history</h2><table class="data-table"><thead><tr><th>Date</th><th>From</th><th>To</th><th>Reason</th></tr></thead><tbody><?php foreach($a['transfers'] as $t):?><tr><td><?=e($t['transferred_at'])?></td><td><?=e($t['from_location_name']??'Unassigned')?></td><td><?=e($t['to_location_name']??'Unassigned')?></td><td><?=e($t['reason'])?></td></tr><?php endforeach;?></tbody></table></section>
<section id="maintenance" class="card table-card"><h2>Maintenance history</h2><table class="data-table"><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Cost</th><th>Capitalized</th></tr></thead><tbody><?php foreach($a['maintenance'] as $m):?><tr><td><?=e($m['maintenance_date'])?></td><td><?=e($m['maintenance_type'])?></td><td><?=e($m['description'])?></td><td><?=e($money($m['cost']))?></td><td><?=!empty($m['capitalized'])?'Yes':'No'?></td></tr><?php endforeach;?></tbody></table></section>
<section id="history" class="card table-card"><h2>Immutable activity history</h2><table class="data-table"><thead><tr><th>Date</th><th>Action</th><th>State</th><th>Details</th></tr></thead><tbody><?php foreach($a['history'] as $h):?><tr><td><?=e($h['occurred_at'])?></td><td><?=e(str_replace('_',' ',$h['action']))?></td><td><?=e(($h['from_status']??'—').' → '.($h['to_status']??'—'))?></td><td><?=e($h['details_json']??'')?></td></tr><?php endforeach;?></tbody></table></section></div>
